(()=>{'use strict';const known=new WeakSet(),states=new Map();function send(f,visible){f.contentWindow?.postMessage({type:'automated-hearts:viewport-activity',active:visible&&!document.hidden},'*');}const io=new IntersectionObserver(entries=>{for(const e of entries){const visible=e.isIntersecting&&e.intersectionRatio>0;states.set(e.target,visible);send(e.target,visible)}},{threshold:0,rootMargin:'0px'});function bind(){for(const f of document.querySelectorAll('iframe')){const src=f.getAttribute('src')||f.dataset.src||'';if(!/machine|model|lab|learning.*html|engine/i.test(src)||known.has(f))continue;known.add(f);states.set(f,false);io.observe(f);f.addEventListener('load',()=>send(f,states.get(f)===true));}for(const [f]of states)if(!f.isConnected){io.unobserve(f);states.delete(f)}}document.addEventListener('visibilitychange',()=>{for(const[f,visible]of states)send(f,visible)});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();let pending=false;new MutationObserver(changes=>{if(!changes.some(m=>[...m.addedNodes,...m.removedNodes].some(node=>node.nodeType===1&&(node.matches?.('iframe')||node.querySelector?.('iframe')))))return;if(pending)return;pending=true;queueMicrotask(()=>{pending=false;bind()})}).observe(document.documentElement,{childList:true,subtree:true});})();
