(()=>{if(!document.body.hasAttribute('data-ah-mobile-surface'))return;const set=(e,p)=>{if(e)for(const[k,v]of Object.entries(p))if(e.style.getPropertyValue(k)!==v)e.style.setProperty(k,v,'important')};function apply(){const section=document.querySelector('main>.lite-section');if(!section||!section.querySelector('[data-lite-learning]'))return;set(section,{'padding-top':'24px'});set(section.querySelector('.ah-brand-digital-cta-band'),{margin:'0 auto 24px','text-align':'center'});set(section.querySelector('.route-grid'),{display:'grid','grid-template-columns':'minmax(0,1fr)','justify-items':'center','text-align':'center',margin:'0 auto',width:'100%'});for(const card of section.querySelectorAll('.route-card')){set(card,{margin:'0 auto',width:'min(100%,340px)',display:'flex','flex-direction':'column','align-items':'center','text-align':'center'});set(card.querySelector('.route-media'),{margin:'0 auto',display:'block'});for(const b of card.querySelectorAll('a,button'))set(b,{'text-align':'center','justify-content':'center',margin:'0 auto'})}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply);else apply();addEventListener('resize',apply);addEventListener('load',apply);})();
